import{_ as t,c as o,o as n,ag as a}from"./chunks/framework.Cycwnjj0.js";const r="/assets/product-advertising-api.CqFwWQYM.webp",s="/assets/aawp-amazon-associates-credentials-1.Bik_cGFD.webp",i="/assets/download-credentials.odhaLt6g.webp",h=JSON.parse('{"title":"Creating Credentials for Amazon Product Advertising API","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuring-amazon-api/creating-credentials-for-amazon-product-advertising-api.md","filePath":"guide/configuring-amazon-api/creating-credentials-for-amazon-product-advertising-api.md"}'),c={name:"guide/configuring-amazon-api/creating-credentials-for-amazon-product-advertising-api.md"};function l(d,e,u,g,p,A){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="creating-credentials-for-amazon-product-advertising-api" tabindex="-1">Creating Credentials for Amazon Product Advertising API <a class="header-anchor" href="#creating-credentials-for-amazon-product-advertising-api" aria-label="Permalink to &quot;Creating Credentials for Amazon Product Advertising API&quot;">​</a></h1><p>The <strong>Amazon API Key</strong> is required for the AzonPress plugin to connect to the <strong>Amazon Product Advertising API</strong>. This enables the plugin to fetch up-to-date product information, display accurate listings, and track affiliate commissions. To set up <strong>Amazon API Keys</strong> in <strong>AzonPress</strong>, you must create the credentials in Amazon first. This article will guide you through creating credentials.</p><h2 id="how-to-create-credentials" tabindex="-1">How to Create Credentials <a class="header-anchor" href="#how-to-create-credentials" aria-label="Permalink to &quot;How to Create Credentials&quot;">​</a></h2><p>To learn how to create credentials in your Amazon Associates Account, follow the steps with the screenshots below –</p><p>First, you need to create an Amazon Associates Account. Now, to create all the credentials for configuring your Amazon account in AzonPress, you need to <strong>request API access</strong>.</p><p>But, you need to meet all the requirements below first, to request and get access to <strong>Product Advertising API.</strong> The requirements are –</p><ul><li>To qualify for requesting access to PA API, you will need an Associates account.</li><li>You will have to complete 3 qualifying sales in the first 180 days and you will have to comply with the Operating Agreement.</li><li>Once your account is approved as an Associates account, you will see a &#39;Request for PA API access&#39; button below. You can click the button to get access to PA API.</li></ul><p><strong>Remember</strong>, if you can&#39;t create credentials properly, your Associates&#39; account will not meet the requirements mentioned above.</p><p>Once you get the PA API access, go to the <strong>Dashboard</strong> of your created <strong>Amazon Associate Account</strong>, click on the <strong>Tools</strong> located on the top navigation bar, and press the <strong>Product Advertising API</strong> from the drop-down menu.</p><p><img src="'+r+'" alt="Azonpress - Create API"></p><p>Next, you will have the option to create your credentials by clicking the <strong>Add Credentials</strong> button.</p><p><img src="'+s+'" alt="Add credential"></p><p>After creating all your credentials properly, you can download them including <strong>Access Key</strong> and <strong>Secret Key</strong> by clicking the <strong>Download Credentials</strong> button.</p><p>Now, you can Configure Amazon API in the AzonPress plugin.</p><p>Remember one thing, if you are using a local Association program, your URL might be different.</p><p><img src="'+i+'" alt="Download Credentials"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p>',17)])])}const f=t(c,[["render",l]]);export{h as __pageData,f as default};
